TLM.f("Tempora/PentEpi4-2",{"officium":"Feria Tertia infra Hebdomadam IV quæ superfuit post Epiphaniam","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/PentEpi4-0","from":{"Introitus":"Tempora/PentEpi4-0","Oratio":"Tempora/PentEpi4-0","Lectio":"Tempora/PentEpi4-0","Graduale":"Tempora/PentEpi4-0","Evangelium":"Tempora/PentEpi4-0","Offertorium":"Tempora/PentEpi4-0","Secreta":"Tempora/PentEpi4-0","Communio":"Tempora/PentEpi4-0","Postcommunio":"Tempora/PentEpi4-0"},"sections":{"Introitus":[{"k":"ref","la":"Jer 29:11; 29:12; 29:14"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."},{"k":"ref","la":"Ps 84:2"},{"k":"text","la":"Benedixísti, Dómine, terram tuam: avertísti captivitátem Jacob."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Dicit Dóminus: Ego cógito cogitatiónes pacis, et non afflictiónis: invocábitis me, et ego exáudiam vos: et redúcam captivitátem vestram de cunctis locis."}],"Oratio":[{"k":"text","la":"Deus, qui nos, in tantis perículis constitútos, pro humána scis fragilitáte non posse subsístere: da nobis salútem mentis et córporis; ut ea, quæ pro peccátis nostris pátimur, te adjuvánte vincámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános."},{"k":"ref","la":"Rom 13:8-10"},{"k":"text","la":"Fratres: Némini quidquam debeátis, nisi ut ínvicem diligátis: qui enim díligit próximum, legem implévit. Nam: Non adulterábis, Non occídes, Non furáberis, Non falsum testimónium dices, Non concupísces: et si quod est áliud mandátum, in hoc verbo instaurátur: Díliges próximum tuum sicut teípsum. Diléctio próximi malum non operátur. Plenitúdo ergo legis est diléctio."}],"Graduale":[{"k":"ref","la":"Ps 43:8-9"},{"k":"text","la":"Liberásti nos, Dómine, ex affligéntibus nos: et eos, qui nos odérunt, confudísti."},{"k":"text","la":"In Deo laudábimur tota die, et in nómine tuo confitébimur in sǽcula. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 8:23-27"},{"k":"text","la":"In illo témpore: Ascendénte Jesu in navículam, secúti sunt eum discípuli ejus: et ecce, motus magnus factus est in mari, ita ut navícula operirétur flúctibus, ipse vero dormiébat. Et accessérunt ad eum discípuli ejus, et suscitavérunt eum, dicéntes: Dómine, salva nos, perímus. Et dicit eis Jesus: Quid tímidi estis, módicæ fídei? Tunc surgens, imperávit ventis et mari, et facta est tranquíllitas magna. Porro hómines miráti sunt, dicéntes: Qualis est hic, quia venti et mare obœ́diunt ei?"}],"Offertorium":[{"k":"ref","la":"Ps 129:1-2"},{"k":"text","la":"De profúndis clamávi ad te, Dómine: Dómine, exáudi oratiónem meam: de profúndis clamávi ad te, Dómine."}],"Secreta":[{"k":"text","la":"Concéde, quǽsumus, omnípotens Deus: ut hujus sacrifícii munus oblátum fragilitátem nostram ab omni malo purget semper et múniat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Marc 11:24"},{"k":"text","la":"Amen, dico vobis, quidquid orántes pétitis, crédite, quia accipiétis, et fiet vobis."}],"Postcommunio":[{"k":"text","la":"Múnera tua nos, Deus, a delectatiónibus terrenis expédiant: et cœléstibus semper instáurent aliméntis."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ba591f95b6d2e86d":{"t":"Jer 29, 11-12.14, Ps 84, 2\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva. (Ps 84, 2) Blagoslovio si, Gospodine, svoju zemlju, na dobro si okrenuo Jakovljevu sudbinu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Jer 29, 11-12.14) Govori Gospodin: Ja mislim misli mira a ne ugnjetavanja. Zazvat ćete me i ja ću vas uslišiti i izbavit ću vas robove iz svih krajeva.","kn":"perem. 29. 11-14). Govori Gospodin: Ja mislim misli mira, a ne cviljenja; prizivat ćete me i ja ću vas uslišati, i izvest ću robovanje vaše iz svih mjesta. (Ps. 84. 2) Blagoslovio si, Gospodine, zemlju svoju, povratio si roblje Jakovljevo. Slava Oću . . . Govori Gospodin .• •","knRef":"Kniewald 1942, str. 432–433 (snimka 217) (OCR)"},"73a6e95fc762642b":{"t":"<i>Pomolimo se</i>.\nBože, koji znaš da zbog ljudske slabosti ne možemo odolijevati tolikim pogiblima, daj nam zdravlje duše i tijela, da ono što trpimo za svoje grijehe svladamo uz tvoju pomoć.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, Ti znaš, da ljudske slaboće radi ne možemo odolijevati tolikim pogiblima; podaj nam, dakle, molimo, zdravlje duše i tijela, da pomoću Tvojom nadvladamo ono, što zaradi grijeha naših trpimo, pp G. n. I. K.","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"0f8fcefc28906709":{"t":"Rim 13, 8-10\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: Nikome ništa ne dugujete, osim da se ljubite među sobom, jer tko ljubi bližnjega ispunio je zakon. Uistinu: Ne učini preljuba, ne ubij, ne ukradi, ne svjedoči krivo, ne poželi, i ako ima još koja zapovijed – sve je sadržano u ovoj: »Ljubi bližnjega svoga kao samog sebe.« Ljubav ne čini zla bližnjemu. Dakle, ljubav je izvršenje zakona.","kn":"Čitanje poslanice bi. Pavla apostola Rimljanima (13, 8-10). Braćol .Nikomu ništa ne dugujte, osim da’ se među sobom ljubite, jer koji ljubi bližnjega, isipunio je zakon. Jer; Ne čini preljuba, ne ubij, ne ukradi, ne svjedoči lažno, ne poželi, i ako ima još kakva zapovijed, uglavljuje se u ovoj; Ljubi svoga bližnjega kao samoga sebe. Tko ljubi bljižnjega, ne čini zla. Izvršenje, dakle, fzakona je ljubav.","knRef":"Kniewald 1942, str. 434–435 (snimka 218) (OCR)"},"a8b02c4b81c26ed7":{"t":"Ps 43, 8-9\nSpasio si nas, Gospodine, od naših protivnika i smeo si naše mrzitelje. U Bogu je naša slava u svako doba, i uvijek hvalimo ime tvoje.\n\nPs 129, 1-2\n<i>Aleluja</i>, <i>aleluja</i>.\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. <i>Aleluja</i>.","kn":"(Ps. 43, 8, 9). Oslobodio si nas, Gospodine, od onih, koji nas mučiše i smeo si one, koji mrziše na nas. U Bogu ćemo se hvaliti cijeli dan. 1 slavit ćemo ime Tvoje u vijeke.\n\nAleluja, aleluja. (Ps. 129, 1, 2) Iz dubine vapijem k Tebi, Gospodine; Gospodine usliši molitvu moju, aleluja. r","knRef":"Kniewald 1942, str. 434–435 (snimka 218) (OCR)"},"363c61b1eee0825d":{"t":"Mt 8, 23-27\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme: Uđe Isus u lađu, a njegovi učenici za njim. I gle, na moru nasta velika oluja, tako da su valovi pokrivali lađu. A on je spavao. Tada njegovi učenici pristupe k njemu, probude ga i reknu mu: Gospodine, spasi nas, pogibosmo! Isus im reče: Što se strašite, malovjerni? Tada ustane, zapovjedi vjetrovima i moru, i nasta velika tišina. A ljudi su začuđeno pitali: Tko je ovaj da ga slušaju vjetrovi i more?","v":"et → ∅","kn":"t Slijedi sveto evanđelje po Matcju (8, 23-27). U ono vrijeme, kad je Isus ušao u lađu, pošli su za njim njegovi učenici. I nasta na moru velika .oluja, tako da su valovi prekrivali lađu, a on je Sipavao. I njegovi učenici prlstupiše k njemu i probude ga govoreći: Gospodine, izbavi nas, pogibosmo! A Isus itm reče: Sto se plašite, malovjemi? Nato ustane, zapovjedi vjetrovima i moru, i nasta velika tišina, A ljudi su se čudili i pitali. Tko je ovaj, da ga slušaju vjetrovi i more?","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"8a9f1217916db598":{"t":"Ps 129, 1-2\nIz dubine vapijem k tebi, Gospodine. Gospodine, usliši moj glas. Iz dubine vapijem k tebi, Gospodine.","kn":"(Ps. 129, 1-2). Iz dubine vapijem k Tebi, Gospodine; Gospodine, usliši molitvu moju; iz dubine vapijem k Tebi, Gospodine.","knRef":"Kniewald 1942, str. 434–435 (snimka 218) (OCR)"},"048b98f96866c762":{"t":"Dopusti, molimo, svemogući Bože, da prikazni dar ove žrtve vazda čisti i brani našu krhku narav od svakoga zla.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, molimo, svemogući Bože, da prikazani dar ove žrtve slabost našu od svakog zla čisti vazda i brani, po G. n. I. K.","knRef":"Kniewald 1942, str. 82–83 (snimka 42) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"2a2aa3c192299041":{"t":"Mk 11, 24\nZaista vam kažem: Što god moleći zaištete, vjerujte da ćete dobiti, i bit će vam.","kn":"(Mk., 11, 24). Zaista vam kažem, štogod moleći zaištete, vjerujte, da ćete primiti, i bit će vam.","knRef":"Kniewald 1942, str. 432–433 (snimka 217) (OCR)"},"96cb53c5249ebbd3":{"t":"<i>Pomolimo se</i>.\nNeka nas, Bože, tvoji darovi odvraćaju od zemaljskih užitaka i vazda krijepe nebeskom hranom.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
